def process_words(text):
    vowels = 'aeiou'
    processed_words = []
    for word in text.split():
        if len(word) % 3 == 0:
            word = word[::-1]
        elif word[0].lower() in vowels:
            word = word.upper()
        else:
            word = word
        processed_words.append(word)
    return '|'.join(processed_words)
```

