def count_paths(grid):
    rows, cols = len(grid), len(grid[0])
    dp = [[0] * cols for _ in range(rows)]
    dp[0][0] = grid[0][0]

    for i in range(rows):
        for j in range(cols):
            if i == 0 and j == 0:
                continue
            if i > 0:
                dp[i][j] += dp[i-1][j]
            if j > 0:
                dp[i][j] += dp[i][j-1]

    for i in range(rows-1, -1, -1):
        for j in range(cols-1, -1, -1):
            if i == rows-1 and j == cols-1:
                continue
            if i > 0:
                dp[i][j] += dp[i][j-1]
            if j > 0:
                dp[i][j] += dp[i-1][j]

    return dp[rows-1][cols-1] % 3
