from collections import deque

def bfs_order(n, edges):
    visited = [False] * n
    order = []

    for u, v in edges:
        if not visited[u]:
            visited[u] = True
            order.append(u)
            queue = deque([u])
            while queue:
                node = queue.popleft()
                for neighbor in graph[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        order.append(neighbor)
                        queue.append(neighbor)

    return order
```

